if isinstance(batch, torch.Tensor):
    return batch.to(device, non_blocking=True)

# If batch is a list or tuple, recursively apply to_cuda to each element
elif isinstance(batch, (list, tuple)):
    return type(batch)(to_cuda(item, device) for item in batch)

# If batch is a dictionary, recursively apply to_cuda to its values, ignoring keys named "meta"
elif isinstance(batch, dict):
    dotdict_batch = dotdict(batch)
    return dotdict_batch.__dict__
    # return {key: to_cuda(value, device) for key, value in dotdict_batch.__dict__.items() if key != "meta"}

# If batch is a numpy array, convert it to a tensor and move it to CUDA
elif isinstance(batch, np.ndarray):
    return torch.as_tensor(batch).to(device, non_blocking=True)

# If batch is of any other type, raise a TypeError
else:
    raise TypeError("Unsupported type for to_cuda function")

from easyvolcap.utils.base_utils import dotdict
import torch

# If batch is a torch tensor, move it to CUDA
if isinstance(batch, torch.Tensor):
    return batch.to(device, non_blocking=True)

# If batch is a list or tuple, recursively apply to_cuda to each element
elif isinstance(batch, (list, tuple)):
    return type(batch)(to_cuda(item, device) for item in batch)

# If batch is a dictionary, create a new dictionary with the values moved to CUDA, unless the key is "meta"
elif isinstance(batch, dotdict):
    new_dict = dotdict()
    for key, value in batch.items():
        if key == "meta":
            new_dict[key] = value
        else:
            new_dict[key] = to_cuda(value, device)
    return new_dict

# If batch is a numpy array, convert it to a tensor and move it to CUDA
elif isinstance(batch, np.ndarray):
    return torch.as_tensor(batch).to(device, non_blocking=True)

# If batch is of any other type, raise a TypeError
else:
    raise TypeError("Unsupported type for to_cuda: {}".format(type(batch)))

