from litdata.streaming.resolver import _resolve_time_template
import pathlib
if isinstance(dir_path, str):
    if dir_path.startswith("s3://"):
        # Create a Dir object with the path and URL attributes set for an S3 URL
        return Dir(path=dir_path, url=dir_path)
    elif dir_path.startswith("local:"):
        # Create a Dir object with just the path attribute for a local path
        return Dir(path=dir_path)
    elif dir_path.startswith("/teamspace/studios"):
        # Use _resolve_studio to handle specific directories like "/teamspace/studios"
        return _resolve_studio(dir_path, None, None)
    else:
        # Use _resolve_time_template to replace time-based placeholders in the path
        dir_path = _resolve_time_template(dir_path)
        # Resolve the path to an absolute path
        absolute_path = pathlib.Path(dir_path).absolute().resolve()
        # Create a Dir object with the absolute path attribute
        return Dir(path=str(absolute_path))
else:
    # If dir_path is not a string, assume it's a Dir object and return it as is
    return dir_path

